INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€32m fund giving free training to job-seekers – is your community benefitting?', 'e32m-fund-giving-free-training-to-job-seekers-is-your-community-benefitting', '<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/TO7ngehltAI/AAAAAAAAAJE/mRJPixIqOGQ/s1600/Labour%2BMarket%2BActivation%2BFund%2B-%2BTipperary.jpg"><span ><span >GEAROID FITZGIBBON REPORTS IN THE NEXT ISSUE </span></span></a></p>
<div><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/TO7ngehltAI/AAAAAAAAAJE/mRJPixIqOGQ/s1600/Labour%2BMarket%2BActivation%2BFund%2B-%2BTipperary.jpg"><span ><span >OF &#8216;CHANGING IRELAND&#8217;:</span></span></a></div>
<div>
<div><img decoding="async" src="https://1.bp.blogspot.com/_cgq3tUEQMDo/TO7nl5lJotI/AAAAAAAAAJM/N1HTBke62jk/s200/Labour%2BMarket%2BActivation%2BFund%2B-%2Bmeath%2Bpartnership.jpg" border="0" alt="" /></p>
<p><span lang="EN-GB"><span><span ><span >While the effectiveness and cohesion of national economic policies are questioned, there are in fact a raft of minor initiatives aimed at boosting the economy. <o:p></o:p></span></span></span></span></p>
<p><span lang="EN-GB"><span ><span >Community and voluntary groups including Local Development Companies have yet to </span></span></span><span >take full advantage of these initiatives.</span></p>
<p><span lang="EN-GB"><span ><span >Many of them are funded under the €32m Labour Market Activation Fund which is “</span></span></span><span lang="EN-GB"><span ><span >to stimulate innovation in the provision of training and activatio</span></span></span><span lang="EN-GB"><span ><span >n</span></span></span><span lang="EN-GB"><span ><span > </span></span></span><span lang="EN-GB"><span ><span >measures for jobseekers seeking to upskill and get back into work</span></span></span><span lang="EN-GB"><span ><span >.”</span></span></span></p>
<p><span lang="EN-GB"><span ><span >It was launched in June.</span></span></span></p>
<p><img decoding="async" src="https://1.bp.blogspot.com/_cgq3tUEQMDo/TO7ntOhUyfI/AAAAAAAAAJU/830eceOrj1U/s200/Labour%2BMarket%2BActivation%2BFund%2B-%2BWexford.png" border="0" alt="" />  </p>
<p><span lang="EN-GB"><span ><span >Of 350 tenders received, 25 were selected, from both private and public bodies. These offer everythi</span></span></span><span >ng from free college places, to short term training in specific skills, eg multimedia, tourism, green economy.  For further information on these, see the Department of E</span><span >ducation and Skills&#8217; website, where a full list of the initiatives can be downloaded.</span></p>
<p><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/TO7oQp_tmuI/AAAAAAAAAJk/TuhnXWjROu4/s200/Labour%2BMarket%2BActivation%2BFund%2B-%2BTipperary.jpg" border="0" alt="" /></p>
<p><span lang="EN-GB"><span ><span >For more inf</span></span></span><span >ormation, look out for our magazine published next week, in print and online at: www.changingireland.ie</span></p>
<p><span lang="EN-GB"><span ><span ><i>CAPTION: The posters here are a selection from around the country offering free training for unemployed people, in these cases in Carlow, Meath and Tipperary.</i></span></span></span></p>
<p>  </div>
</div>', 'GEAROID FITZGIBBON REPORTS IN THE NEXT ISSUE OF ‘CHANGING IRELAND’: While the effectiveness and cohesion of national economic policies are questioned, there are in fact a raft of minor initiatives aimed at boosting the economy. Community and voluntary groups including Local Development Companies have yet to take full advantage of these initiatives. Many of them', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 324, 1, '2010-11-25T22:17:00Z', '2019-07-23T12:18:54Z', '2010-11-25T22:17:00Z')
