INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Cuts of €35m over 4 years to Dept of Community, Rural & Gaeltacht Affairs', 'cuts-of-e35m-over-4-years-to-dept-of-community-rural-gaeltacht-affairs', '<p><span ><span >Cuts of €35m are planned for the Department of Community, Equality and Gaeltacht Affairs from 2011-2014.<br />The chart below covers some details of the cuts for the coming year, 2011. It comes from the Government&#8217;s official four-year plan which is </span></span><a href="https://www.progressive-economy.ie/2010/11/national-recovery-plan.html"><span ><span >downloadable from this page.</span></span></a></p>
<div><span ><span >The Community Workers Co-op have published a 7-page response to the budget from a Community viewpoint:<br /><a href="https://www.cwc.ie/wp-content/uploads/2010/11/CWC-Community-Work-Updates-November-2010.pdf">https://www.cwc.ie/wp-content/uploads/2010/11/CWC-Community-Work-Updates-November-2010.pdf</a></span></span></div>
<div><span ><span ><span ><a href="https://www.progressive-economy.ie/2010/11/national-recovery-plan.html"></a></span></span></span><span ><span ><br />Your opinion?</span></span></p>
<div>
<div><span ><span >CLICK TO ENLARGE</span></span></div>
<p><span ></span><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/TO01pleC_0I/AAAAAAAAAIk/QHGivKcJs90/s1600/Picture%2B13.png"><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/TO01pleC_0I/AAAAAAAAAIk/QHGivKcJs90/s400/Picture%2B13.png" border="0" alt="" /></a></div>
</div>', 'Cuts of €35m are planned for the Department of Community, Equality and Gaeltacht Affairs from 2011-2014.The chart below covers some details of the cuts for the coming year, 2011. It comes from the Government’s official four-year plan which is downloadable from this page. The Community Workers Co-op have published a 7-page response to the budget', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 328, 1, '2010-11-24T15:47:00Z', '2019-09-13T10:57:23Z', '2010-11-24T15:47:00Z')
