INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('WE DIDN’T ALL CAUSE THIS MESS! WE HAVE OUR PRIDE!', 'we-didnt-all-cause-this-mess-we-have-our-pride', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TOXW-ylPLUI/AAAAAAAAAIc/ZA9_km_tctI/s1600/IRISH-FLAG.jpg"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TOXW-ylPLUI/AAAAAAAAAIc/ZA9_km_tctI/s400/IRISH-FLAG.jpg" border="0" alt="" /></a>   </p>
<p><span lang="EN-GB" >HOW DO YOU FEEL TODAY?<o:p></o:p></span></p>
<p><span lang="EN-GB" >asks ALLEN MEAGHER, EDITOR</span></p>
<p><span lang="EN-GB" >We&#8217;ve invited in foreigners to take over the running of our country&#8217;s finances and decide our future for the years to come. We&#8217;ve lost a large part of our sovereignty.</span></p>
<p><span lang="EN-GB" ></span><span >There is anger in the air and even some Government TDs have felt it and have called on the Government to resign.</span></p>
<p><span lang="EN-GB" >THE QUESTION IS WHAT WOULD BEST SERVE THE INTERESTS OF IRELAND&#8217;S DISADVANTAGED COMMUNITIES NOW? <o:p></o:p></span></p>
<p><span >FOLLOW WHAT OUR READERS HAVE TO SAY ON </span><span ><a href="https://www.facebook.com/pages/Changing-Ireland/195484689356">OUR FACEBOOK PAGE</a></span></p>
<p>  </p>', 'HOW DO YOU FEEL TODAY? asks ALLEN MEAGHER, EDITOR We’ve invited in foreigners to take over the running of our country’s finances and decide our future for the years to come. We’ve lost a large part of our sovereignty. There is anger in the air and even some Government TDs have felt it and have', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 329, 1, '2010-11-19T01:46:00Z', '2019-09-13T10:57:31Z', '2010-11-19T01:46:00Z')
