INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New ideas workshop on Nov 24th in Dublin', 'new-ideas-workshop-on-nov-24th-in-dublin', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TNfxjFDcjRI/AAAAAAAAAIE/JA1TkKM2Bto/s1600/Tosach+training+2010+PIC.jpg"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TNfxjFDcjRI/AAAAAAAAAIE/JA1TkKM2Bto/s200/Tosach+training+2010+PIC.jpg" border="0" alt="" /></a><span ><span >We&#8217;re all looking for new ideas in these &#8220;challenging&#8221; times and Tosach is holding an innovation workshop in St. Andrew&#8217;s Resource Centre in Dublin 2, on November 24th. At €25 per person, it&#8217;s good value compared to certain profit-making companies who charge 10 times that for their expertise. </span></span></p>
<div><span ><span >It will cover:</span></span></div>
<div>
<li><span ><span >Using Social Media to build community </span></span></li>
<li><span ><span >Building a sustainable social enterprise </span></span></li>
<li><span ><span >Using successful role models in education &#8211; A positive deviance approach<br /></span></span></li>
<li><span ><span >Engaging Drug Users with the Arts </span></span></li>
<li><span ><span >Restorative Justice &#8211; A new way of dealing with anti-social behaviour?</span></span></li>
<li><span ><span >Mental Health &#8211; a community issue in recession </span></span></li>
</div>
<div><span  >Facilitators include Tony Cronin, Bernie Walsh, Gerry McKeever, Eoghan O&#8217;Neill and Karl Tooher.</span></div>
<div><span  ><br /></span></div>
<div><a href="https://tosach.ie/s/new-ideas-for-challenging-times/"><span><span ><span ></span></span></span><span ><span >More info: www.tosach.ie</span></span></a></div>
<div><span ><span ><br /></span></span></div>
<div>
<li><span ><span >Tosach is a Dublin-based not-for-profit that offers support services to the Community and Voluntary Sector. It worked with CDPs for many years in a formal capacity as a support agency. </span></span></li>
</div>', 'We’re all looking for new ideas in these “challenging” times and Tosach is holding an innovation workshop in St. Andrew’s Resource Centre in Dublin 2, on November 24th. At €25 per person, it’s good value compared to certain profit-making companies who charge 10 times that for their expertise. It will cover: Using Social Media to', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 331, 1, '2010-11-08T12:41:00Z', '2010-11-08T12:41:00Z', '2010-11-08T12:41:00Z')
