INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Disability leader proposes land taxes instead of cuts', 'disability-leader-proposes-land-taxes-instead-of-cuts', '<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/TNK_42kPF4I/AAAAAAAAAH8/s7-03a5pPX4/s1600/Picture+8.png"><img decoding="async" src="https://3.bp.blogspot.com/_cgq3tUEQMDo/TNK_42kPF4I/AAAAAAAAAH8/s7-03a5pPX4/s200/Picture+8.png" border="0" alt="" /></a><span><span><span >&#8220;I believe a €5 land tax per acre regardless of the quality of the land could yield a massive €8 billion per year straight into the coffers of Government,&#8221; says Noel O&#8217;Neill, chairperson of the Kerry Network of People with Disabilities.</span></span></span></p>
<div><span ><span><span >   </span></span></p>
<p><span><span >While his figures don’t seem to stack up (see comments below) he makes the point that there is untapped wealth in this country and h</span></span><span><span >e argues that the poor can&#8217;t pay for the banks&#8217; collapse.</span></span></p>
<p></span></p>
<div>
<div>
<div>
<div><span><span><span >On his specific proposal, Noel says farmers he knows agree with him. If you want to read more advice (2 pages) to the Government on the upcoming budget from the KNPD, </span></span><a href="https://docs.google.com/fileview?id=0Bw2kPUIQq1MbODlhNjM2ZjgtMTI2Zi00OTlkLWE1NDktZmNmYWQ1MmYzYTNh&amp;hl=en&amp;pli=1"><span><span >click the link here.</span></span></a></span></div>
</div>
<div><span><span><span ><br /></span></span></span></div>
<div><span><span><span ><span><span >BACKGROUND: The KNPD is one of 160 Community Development Projects that are part of the LCDP. </span></span></span><span><span><span >The project is currently amalgamating with the North East Kerry Development Company. </span></span></span></span></span></div>
<div><span  ><br /></span></div>
</div>
</div>
</div>', '“I believe a €5 land tax per acre regardless of the quality of the land could yield a massive €8 billion per year straight into the coffers of Government,” says Noel O’Neill, chairperson of the Kerry Network of People with Disabilities. While his figures don’t seem to stack up (see comments below) he makes the', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 332, 1, '2010-11-04T13:51:00Z', '2010-11-04T13:51:00Z', '2010-11-04T13:51:00Z')
