INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Find out about ‘Community Economic Development (CED) Lawyering’ HERE!', 'find-out-about-community-economic-development-ced-lawyering-here', '<p><a href="https://1.bp.blogspot.com/_cgq3tUEQMDo/TNGSPKn1R5I/AAAAAAAAAH0/f8Y5ZPtEfuY/s1600/ISS+34-NestorMA.jpg"><img decoding="async" src="https://1.bp.blogspot.com/_cgq3tUEQMDo/TNGSPKn1R5I/AAAAAAAAAH0/f8Y5ZPtEfuY/s320/ISS+34-NestorMA.jpg" border="0" alt="" /></a><span ><br /></span><span ><span >There is lot of information available on the internet about a phenomena well rooted in communities in the USA called &#8216;Community Economic Development (CED) Lawyering&#8217;. </span></span></p>
<div><i><span lang="EN-GB"><span ><span >Maria Antonieta Nestor (pictured here) has written an article on the subject for the autumn edition of ‘Changing Ireland’</span></span></span></i><span lang="EN-GB"><span ><span > and recommends the following (click for links)</span></span></span><span ><span >:</span></span></div>
<div><a href="https://www.communitybenefits.org/section.php?id=163"><span ><span >• Community Benefit Agreements,<br /></span></span></a><span ><span >• </span></span><a href="https://www.ndlon.org/"><span ><span >National Day Labourer Organisation Network</span></span></a><span ><span >,<br />• </span></span><a href="https://www.cleancarwashla.org/"><span ><span >CLEAN CarWash campaig</span></span></a><span ><span >n,<br />• </span></span><a href="https://www.loncheros.com/"><span ><span >Taco Truck</span></span></a><span ><span >s (information partly in Spanish),<br />• For inspiration on how community education can make a difference, visit the </span></span><a href="https://www.idepsca.org/"><span ><span >Institute of Popular Education of Southern California (IDEPSCA)</span></span></a><span ><span >,<br />• </span></span><a href="https://www.saje.net/site/c.hkLQJcMUKrH/b.2315787/k.27E1/What_We_Do.htm%3E%20and%20%3Chttps://www.laane.org/about-us/what-we-do"><span ><span >Economic justice work of community coalitions</span></span></a><span ><span >,<br />• </span></span><a href="https://www.lapilj.org/2008-09-narro-article.html"><span ><span >Immigrant initiatives in Los Angele</span></span></a><span ><span >s, particularly as reported by Victor Narro,<br />• For an academic view on CED you can also read the scholarly works of Scott Cummings, Susan Bennett, Susan Jones and Roger A. Clay Jr.</p>
<p></span></span></p>
<div><span ><span >***</span></span></div>
<p><span ><span >At a glance, some CED initiatives in Ireland are:<br />• The </span></span><span ><span ><a href="https://www.bclc.ie/legal_education_programme/legal_education_programme__autumn___winter_2010_2011.604.html">Legal Education Programme at the Ballymun Community Law Centr</a></span></span><span ><span ><a href="https://www.bclc.ie/legal_education_programme/legal_education_programme__autumn___winter_2010_2011.604.html">e</a><br />• The work of the </span></span><a href="https://www.limerickregeneration.ie/"><span ><span >Limerick Regeneration Agencies </span></span></a><span ><span ><br />• The </span></span><a href="https://www.shelltosea.com/content/campaign-inf"><span ><span >Shell-to-Sea Campaign</span></span></a><span ><span ><br /></span></span></p>
<div><span ><span ><br /></span></span></div>
<div><span ><span >Are there any others you&#8217;d suggest? Comments welcome. </span></span></div>
<div><span ><span ><br /></span></span></div>
<div>  </p>
<p><span><span lang="EN-IE"><span ><span >* Maria Antonieta Nestor is a PhD student at the School of Law, TCD. Her research project is looking at CED lawyering in the USA and comparing it with what is happening on the ground in Ireland. </span></span></span></span><span lang="EN-IE"><span ><span ><o:p></o:p></span></span></span></p>
<p><span lang="EN-IE" ><span ><span >If you would like to contact the author about your experiences, examples or questions about CED, email: nestorma@tcd.ie</span></span><o:p></o:p></span></p>
<p>     </div>
</div>', 'There is lot of information available on the internet about a phenomena well rooted in communities in the USA called ‘Community Economic Development (CED) Lawyering’. Maria Antonieta Nestor (pictured here) has written an article on the subject for the autumn edition of ‘Changing Ireland’ and recommends the following (click for links): • Community Benefit Agreements,•', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 333, 1, '2010-11-03T16:38:00Z', '2019-07-23T12:18:35Z', '2010-11-03T16:38:00Z')
