INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('VIDEO REPORTS FROM ‘CLAIMING OUR FUTURE’', 'video-reports-from-claiming-our-future', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TM71x6--77I/AAAAAAAAAHs/siJdxP1OgPM/s1600/Picture+3.png"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TM71x6--77I/AAAAAAAAAHs/siJdxP1OgPM/s400/Picture+3.png" alt="" border="0" /></a><span ><span ></p>
<p></span></span><span></p>
<h3 ft="{&quot;type&quot;:&quot;msg&quot;}" ><span><span ><span >We&#8217;re uploading video reports from Saturday&#8217;s historic &#8216;Claiming Our Future&#8217; event, the biggest Civil Society gig in the Republic Ireland in a generation.<br />It wasn&#8217;t a protest and it was different. And it achieved its aim of finding out what we&#8217;re FOR in a new Irelan</span></span><span><span ><span >d. The top 3 values a new Ireland needs to emphasise, according to the final vote, are:<br />&#8211; equality,<br />&#8211; environmental sustainability<br />-and accountability</p>
<p>Also popular were policies leading to better governance and a maximum wage as well as the minimum wage.</p>
<p>Our first video is with Niamh McGrath aka &#8216;The elephant in the room&#8217;.<br /></span></span><a href="https://www.youtube.com/watch?v=R4m6TL0Uo2Q&amp;feature=player_embedded" rel="nofollow noopener noreferrer" target="_blank"><span ><span ><object width="480" height="385"><param name="movie" value="https://www.youtube.com/v/R4m6TL0Uo2Q?fs=1&amp;hl=en_US&amp;rel=0"></param><param name="allowFullScreen" value="true"></param><param name="allowscriptaccess" value="always"></param><embed src="https://www.youtube.com/v/R4m6TL0Uo2Q?fs=1&amp;hl=en_US&amp;rel=0" type="application/x-shockwave-flash" allowscriptaccess="always" allowfullscreen="true" width="480" height="385"></embed></object></span></span></a><span ><span ><br />An in-depth and lively 11-minute interview with one of the organisers Siobhan O&#8217;Donohue is now online at<br /></span></span></span></span></h3>
<p>https://www.youtube.com/watch?v=yqfm945n77U</p>
<p><object height="385" width="480"><param name="movie" value="https://www.youtube.com/v/yqfm945n77U?fs=1&amp;hl=en_US&amp;rel=0"><param name="allowFullScreen" value="true"><param name="allowscriptaccess" value="always"><embed src="https://www.youtube.com/v/yqfm945n77U?fs=1&amp;hl=en_US&amp;rel=0" type="application/x-shockwave-flash" allowscriptaccess="always" allowfullscreen="true" height="385" width="480"></embed></object></p>
<p></span></p>', 'We’re uploading video reports from Saturday’s historic ‘Claiming Our Future’ event, the biggest Civil Society gig in the Republic Ireland in a generation.It wasn’t a protest and it was different. And it achieved its aim of finding out what we’re FOR in a new Ireland. The top 3 values a new Ireland needs to emphasise,', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 334, 1, '2010-11-01T17:11:00Z', '2019-07-23T12:18:35Z', '2010-11-01T17:11:00Z')
