INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Britain’s Community Budget CUT; Overseas Aid Budget INCREASES!', 'britains-community-budget-cut-overseas-aid-budget-increases', '<div><span  >While the newly elected Government in Britain has made a lot of noise about plans to give local authorities and communities more say in how money is spent, there will be an awful lot less funding available. </span></div>
<div><span ><span ><span  ><img loading="lazy" decoding="async" src="https://d.yimg.com/i/ng/ne/politics/20101020/16/3431767286-spending-review-communities-culture-damage.jpg#300,225" width="300" height="225" alt="" /></span></span></span></div>
<div><span ><span ><span  ></span>The budget announced in London yesterday outlined mostly bad news for marginalised groups as the Department with responsibility for communities is due to drop spending by 33%.</span></span></div>
<div><span ><span >NGOs have commented on how the greater democratic involvement of communities promised by the Government will be negated by the loss of essential funding to communities.</span></span></div>
<div><span ><span >On the plus side and there were pluses, Britain&#8217;s overseas aid budget is being INCREASED!</span></span></div>
<div><span ><span ><br /></span></span></div>
<div><span ><span ><b>Comments welcome and keep an eye on our international page(s) in our print edition of &#8216;Changing Ireland&#8217;.</b></span></span></div>
<div><span ><span ><br /></span></span></div>
<div><span ><span >Find out more about the UK budget cuts and policy changes for community funding/decision-making:</span></span></div>
<div><span ><span >1. </span></span><a href="https://uk.news.yahoo.com/14/20101020/tpl-spending-review-communities-and-cult-81c5b50.html"><span ><span >Communities and culture take the damage</span></span></a><span ><span > (Yahoo news)</span></span></div>
<div><span ><span >2. <a href="https://www.ncvo-vol.org.uk/news/politics/spending-review-our-response">Response to the cuts by Britain&#8217;s National Council for Voluntary Organisations</a></span></span><span ><span > (NCVO website)</span></span></div>
<div><span ><span >3. <a href="https://www.oxfamblogs.org/ukpovertypost/2010/10/government-spending-cuts-and-bme-women%E2%80%99s-groups/">Oxfam UK Poverty Post &#8211; news, feature and o</a></span></span><span ><span ><a href="https://www.oxfamblogs.org/ukpovertypost/2010/10/government-spending-cuts-and-bme-women%E2%80%99s-groups/">pinion in one short article about the cuts in Britain</a> (an Oxfam blog)</span></span></div>
<div><span ><span ></span></span><span  >4. <a href="https://www.rudi.net/node/22227">CLG budget cut by 51%; local councils by 28%; green investment bank launched; plans for &#8216;dramatic shift&#8217; to the local confirmed</a> (Urban development news website)</span></div>
<div><span  >5 </span><span  ><a href="https://www.communities.gov.uk/corporate/about/">Department&#8217;s short and simple rationale for &#8220;shifting power&#8221; to communities.</a></span><span  > (Official Govt Website)</span></div>
<div></div>', 'While the newly elected Government in Britain has made a lot of noise about plans to give local authorities and communities more say in how money is spent, there will be an awful lot less funding available. The budget announced in London yesterday outlined mostly bad news for marginalised groups as the Department with responsibility', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 335, 1, '2010-10-21T01:06:00Z', '2019-07-23T12:18:35Z', '2010-10-21T01:06:00Z')
