INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Advertise with ‘Changing Ireland’!', 'advertise-with-changing-ireland', '<p><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/TL8WuuUkmJI/AAAAAAAAAHk/27tY1ffNm-Y/s1600/IMG_0247.JPG"><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/TL8WuuUkmJI/AAAAAAAAAHk/27tY1ffNm-Y/s400/IMG_0247.JPG" border="0" alt="" /></a>   </p>
<p><b><span lang="EN-GB">Advertise with ‘Changing Ireland’!<o:p></o:p></span></b></p>
<p><b><span lang="EN-GB">Because now – for the first time – you can!!</span></b></p>
<p><span >Changing Ireland’, the country’s most widely read Community and Voluntary Sector magazine, is now taking advertising for the first time.</span></p>
<p><span lang="EN-GB"><span >Established in 2001, it has built up a loyal readership and reaches up to 15,000 people directly with its printed quarterly publication.</span></span></p>
<p><span><span >‘Changing Ireland’ has also built up a considerable online following via youtube (13,000 views and rising), facebook, blogger and its website</span><b><span >: </span><a href="https://changingireland.ie/"><span >www.changingireland.ie</span></a></b></span></p>
<p><span lang="EN-GB"><span >Our <b><a href="https://docs.google.com/document/pub?id=1ify5NPzLHz5qF61NwPmipnYkV2Y6t8wjbrWZwizom28">COMMERCIAL ADVERTISING RATE CARD is now available online. CLICK HERE!</a></b></span></span></p>
<p><span lang="EN-GB"><span >A separate rate card with substantial discounts is available on request to not-for-profit organisations, in line with our believe that groups working with vulnerable people and marginalised communities should be given the opportunity to advertise even if their budget is small. </span></span></p>
<p><span ><span>Adverts (discounted) start from €133 each (for 1/6th-page).</span></span></p>
<p><span lang="EN-GB"><span >Contact ‘Changing Ireland’ administrator Tim Hourigan (Mon-Wed by phone) or email him anytime to place an advert. T: 061-458090. E: </span><a href="mailto:admin@changingireland.ie"><span >admin@changingireland.ie</span></a></span></p>
<p><span lang="EN-GB"><span >For further queries, contact the editor, Allen Meagher. T: 061-458011. E: </span><a href="mailto:editor@changingireland.ie"><span >editor@changingireland.ie</span></a></span></p>
<p><span lang="EN-GB"><o:p> </o:p></span></p>
<p></p>', 'Advertise with ‘Changing Ireland’! Because now – for the first time – you can!! Changing Ireland’, the country’s most widely read Community and Voluntary Sector magazine, is now taking advertising for the first time. Established in 2001, it has built up a loyal readership and reaches up to 15,000 people directly with its printed quarterly', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 336, 1, '2010-10-20T16:11:00Z', '2010-10-20T16:11:00Z', '2010-10-20T16:11:00Z')
