INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('‘Changing Ireland’ wants to tell the world your News!', 'changing-ireland-wants-to-tell-the-world-your-news', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TOEbIX4t15I/AAAAAAAAAIM/mD6JcDXIGlI/s1600/C.I.%2Bletterhead%2Bcopy.jpg"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TOEbIX4t15I/AAAAAAAAAIM/mD6JcDXIGlI/s320/C.I.%2Bletterhead%2Bcopy.jpg" border="0" alt="" /></a><span><span lang="EN-GB" ></p>
<div>If you&#8217;re working in a Community Development Project or a Local Development Company,</div>
<p>let us know what you&#8217;re doing that’s:<br />(a) different and an example of good practice,<br />(b) that respects Community Development principles and makes a real difference for ordinary punters,<br />(c) that other readers throughout Ireland might like to emulate.</p>
<p>Phone the editor on 061-458011 with your news. Or email: editor@changingireland.ie</p>
<p>Our print magazine  goes to 5000 addresses. Where useful, we also post news here on our blog, Youtube channel and/or Facebook page.</span></p>
<p></span></p>', 'If you’re working in a Community Development Project or a Local Development Company, let us know what you’re doing that’s:(a) different and an example of good practice,(b) that respects Community Development principles and makes a real difference for ordinary punters,(c) that other readers throughout Ireland might like to emulate. Phone the editor on 061-458011 with', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 337, 1, '2010-10-14T14:50:00Z', '2010-10-14T14:50:00Z', '2010-10-14T14:50:00Z')
