INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Event: Claiming Our Future on Oct 30th in Dublin', 'event-claiming-our-future-on-oct-30th-in-dublin', '<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/TLcYCxYqfUI/AAAAAAAAAHU/ekAU01YQ5IE/s1600/Picture+4.png"><img decoding="async" src="https://3.bp.blogspot.com/_cgq3tUEQMDo/TLcYCxYqfUI/AAAAAAAAAHU/ekAU01YQ5IE/s320/Picture+4.png" alt="" border="0" /></a></p>
<h3><span><span>&#8216;Claiming Our Future&#8217; is a day-long event to plot and plan for a better Ireland. The  organisers want to pinpoint the values a better Ireland can aspire to.  Honesty and fair <span>&#8230;</span><span>play for instance. They want to “mobilize” and “unite” Ireland behind a new plan.<br />It takes place in the Industries Hall of the RDS in Dublin City on Saturday, 30th October, from 9am-5.30pm and entry is free.<br /></span></span></span></h3>
<h3><span><span><span><a href="https://www.facebook.com/ClaimingOurFuture" target="_blank" rel="nofollow noopener noreferrer"><span>https://www.facebook.com/ClaimingOurFutur</span><span></span>e</a><br /><a href="https://www.claimingourfuture.ie/" rel="nofollow noopener noreferrer" target="_blank">https://www.claimingourfuture.ie/</a></span></span></span></h3>
<h3><span><span><span>The day is being organised by community activists, trade  unionists, academics, rights groups and umbrella bodies from the  Community and Voluntary Sector. They include: Is Féidir Linn, ICTU,  TASC, Social Justice Ireland, the Community Platform and the  Environmental Pillar of Social Partnership.<br /></span></span></span></h3>
<h3><span><span><span>NOTE: The ‘Is Feidir  Linn’ group was slagged off in an opinion piece in the Summer edition of  &#8216;Changing Ireland&#8217; (they&#8217;re writing a reply). They were accused of  failing to reach the wider public, of not having a message the average  punter would buy into. In fairness to ‘Is Feidir Linn’, they were  planning ahead when others were pulling their hair out and the ‘Claiming  Our Future’ event could not have been held at a better time.<br /></span></span></span></h3>', '‘Claiming Our Future’ is a day-long event to plot and plan for a better Ireland. The organisers want to pinpoint the values a better Ireland can aspire to. Honesty and fair …play for instance. They want to “mobilize” and “unite” Ireland behind a new plan.It takes place in the Industries Hall of the RDS in', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 338, 1, '2010-10-14T14:38:00Z', '2010-10-14T14:38:00Z', '2010-10-14T14:38:00Z')
