INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Galway helps lead the Campaign to Defend Ireland’s Communities', 'galway-helps-lead-the-campaign-to-defend-irelands-communities', '<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/TKxhsbWnaYI/AAAAAAAAAHM/HXwz_STWepY/s1600/image002.jpg"><img decoding="async" src="https://3.bp.blogspot.com/_cgq3tUEQMDo/TKxhsbWnaYI/AAAAAAAAAHM/HXwz_STWepY/s400/image002.jpg" border="0" alt="" /></a></p>
<div>150 or so people turned out in Galway and up to 1500 in Dublin on Sept 29th, 2010, to &#8216;Defend Ireland&#8217;s Communities&#8217;. </div>
<div>In Galway, activists used street theatre to show how community groups who work together are more likely to be successful in fending off attacks and cutbacks. </div>
<div>The trade unions SIPTU and IMPACT are supporting the &#8216;Defending Ireland&#8217;s Communities&#8217; campaign, as are the Community Workers Co-op, Community Platform among others.</div>
<div></div>
<div>What do you think of the turnout? RTE were critical, the trade unions defensive. Comments welcome!</div>
<div></div>
<div>Check out our photo-report from Galway<a href="https://www.facebook.com/album.php?aid=247783&amp;id=195484689356&amp;saved"> by clicking this link to our Facebook page.</a></div>
<div></div>
<div>We&#8217;re also about to post some videos from the demo on <a href="https://www.youtube.com/user/changingireland">our youtube channel</a></div>', '150 or so people turned out in Galway and up to 1500 in Dublin on Sept 29th, 2010, to ‘Defend Ireland’s Communities’. In Galway, activists used street theatre to show how community groups who work together are more likely to be successful in fending off attacks and cutbacks. The trade unions SIPTU and IMPACT are', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 339, 1, '2010-10-06T11:36:00Z', '2010-10-06T11:36:00Z', '2010-10-06T11:36:00Z')
