INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Irish Times covers Changing Ireland article on racist Facebook sites.', 'irish-times-covers-changing-ireland-article-on-racist-facebook-sites', '<p>Allen&#8217;s article in the Irish Times from August 16th relating to our cover story of community groups battling racist websites.<br /><a href="https://www.irishtimes.com/newspaper/ireland/2010/0816/1224276886822.html">Garda issue warning over online racism</a></p>', 'Allen’s article in the Irish Times from August 16th relating to our cover story of community groups battling racist websites.Garda issue warning over online racism', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 341, 1, '2010-08-17T08:40:00Z', '2019-09-13T10:58:57Z', '2010-08-17T08:40:00Z')
