INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Limerick CDPs’ alternative model – details published here', 'limerick-cdps-alternative-model-details-published-here', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TFF_cvioFUI/AAAAAAAAAGk/v0CCX-PP8bk/s1600/Limerick+King+John%27s+Castle.png"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TFF_cvioFUI/AAAAAAAAAGk/v0CCX-PP8bk/s200/Limerick+King+John%27s+Castle.png" border="0" alt="" /></a></p>
<p><span><span ><span >CDPs across the country are currently integrating into the Local and Community Development Programme and some have sought to win approval for an alternative structure that better suits their communitys&#8217; needs.</span></span></span></p>
<p><span lang="EN-GB"><a href="https://changingireland.ie/LimerickCDPsAlternativeModel.doc"><b><span ><span ><span >The Limerick model for setting up a Citywide CDP, as looked on favourably by the Department of Community, Equality and Gaeltacht Affairs is now available online (click here</span></span></span></b><span ><span ><span >)</span></span></span></a><span ><span ><span >. </span>The document gives details of the proposed new voluntary management structure and may be of interest to projects in other parts of the country considering their options.</span></span></span></p>
<p><span lang="EN-GB"><span></span></span></p>
<p><span lang="EN-GB"><span ><span >The Limerick model proposes “</span></span></span><span lang="EN-IE"><span ><span >that instead of ‘integrating’ Partnerships and CDP’s in Limerick city, CDPs are amalgamated into one “City CDP” thus retaining local voluntary involvement with real responsibility and a continued say in decisions affecting their community.”<o:p></o:p></span></span></span></p>
<p><span lang="EN-GB"><span ><span >Limerick CDPs are </span></span></span><span lang="EN-IE"><span ><span >aiming to “ensure that the LCDP is delivered as effectively and efficiently as possible with the maximum participation and buy in from volunteers engaged over the years on CDP management committees.”</span></span></span></p>
</p>
<p><span><span ><span >In Cork, CDPs have developed another alternative in co-operation with the HSE, while Women’s CDPs and Traveller CDPs are also understood to be at advanced stages in working out with the Department how a different model could work for their CDPs and their communities’ needs.</span></span></span></p>
<p><span lang="EN-GB"><span ><span >In most parts of the country, CDPs are being absorbed into Local Development Companies (aka Partnerships) and many if not most of them are likely to close down as companies.<o:p></o:p></span></span></span></p>
<p><span lang="EN-GB"><span ><span >An alternative model proposed by Donegal CDP’s was not accepted by the Department.</span></span></span></p>
<p><span><span ><span >The Department have been clear that they want savings made in the areas of staff, HR, audit, administration and legal bills.</span></span></span></p>
<p>  </p>', 'CDPs across the country are currently integrating into the Local and Community Development Programme and some have sought to win approval for an alternative structure that better suits their communitys’ needs. The Limerick model for setting up a Citywide CDP, as looked on favourably by the Department of Community, Equality and Gaeltacht Affairs is now', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 343, 1, '2010-07-29T13:03:00Z', '2010-07-29T13:03:00Z', '2010-07-29T13:03:00Z')
