INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Moyross.ie launched today by Minister Carey', 'moyross-ie-launched-today-by-minister-carey', '<p><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/TE8RGwXTb0I/AAAAAAAAAGc/1aGcAadTcU8/s1600/Launch+of+Moyross+dot+ie.JPG"><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/TE8RGwXTb0I/AAAAAAAAAGc/1aGcAadTcU8/s320/Launch+of+Moyross+dot+ie.JPG" alt="" border="0" /></a></p>
<p><span lang="EN-GB"><span><span>18 months ago, the first ten items that came up in a Google search for ‘Moyross’ were all negative in the extreme </span></span><span><span><span>characterising the estate solely in terms of criminality and gangs. </span></span></span></span></p>
<p><span lang="EN-GB"><span><span>A new website Moyross.ie is nowadays often listed in the top three Google listings for Moyross. </span></span></span></p>
<p></p>
<p><span lang="EN-GB"><span><span>At lunchtime today, July 27</span></span><sup><span><span>th</span></span></sup><span><span>, the Minister for Community, Equality and Gaeltacht Affairs, Pat Carey, officially launched </span></span></span><a href="https://www.moyross.ie/"><span><span>www.moyross.ie</span></span></a><span><span>, an </span></span><a href="https://cdnmoyross.blogspot.com/"><span><span>accompanying blog</span></span></a><span><span> and </span></span><a href="https://www.youtube.com/user/changingireland"><span><span>‘Changing Ireland’s Youtube channe</span></span></a><span><span>l which passed the 10,000 viewers mark earlier this year.</span></span></p>
<div><span><span>The Moyross website and blog are supported locally by ‘Changing Ireland’.</span></span></div>
<div><span><span>The website builds on the popularity of the local newsletter ‘Moywrites’ produced by the Community Development Network Moyross and it utilises the IT skills and media expertise of ‘Changing Ireland’ staff based in the community, at no extra cost. </span></span></div>
<div><span> </span></div>
<div><span>Meanwhile, work by the PAUL Partnership is ongoing to develop an integrated website for community groups across Limerick City &#8211; Limerickcommunities.ie and Moyross.ie will in time become part of and linked with this.</span></div>
<div>
<p>&nbsp;</p>
<p>CAPTION:<i> CDN Chairperson Deirdre O&#8217;Driscoll, </i><i><span><i><span><i><span><i>Minister Pat Carey and </i></span></i></span></i></span></i><i><span><i>Allen Meagher, editor of &#8216;Changing Ireland&#8217; </i></span></i><i>at the launch of: www.moyross.ie</i></p>
<p></p>
</div>', '18 months ago, the first ten items that came up in a Google search for ‘Moyross’ were all negative in the extreme characterising the estate solely in terms of criminality and gangs. A new website Moyross.ie is nowadays often listed in the top three Google listings for Moyross. At lunchtime today, July 27th, the Minister', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 344, 1, '2010-07-27T16:52:00Z', '2019-08-26T10:21:22Z', '2010-07-27T16:52:00Z')
