INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Examiner gives front page to 4,500 job cuts in Community Sector', 'examiner-gives-front-page-to-4500-job-cuts-in-community-sector', '<p><a href="https://3.bp.blogspot.com/_cgq3tUEQMDo/TCsiceXsU3I/AAAAAAAAAF0/2JgCFu2HuN8/s1600/Examiner+lead+story+June+28,+2010.JPG"><img decoding="async" src="https://3.bp.blogspot.com/_cgq3tUEQMDo/TCsiceXsU3I/AAAAAAAAAF0/2JgCFu2HuN8/s200/Examiner+lead+story+June+28,+2010.JPG" border="0" alt="" /></a><span  ></p>
<p><span ><span >Research work last month by Brian Harvey and IMPACT showed that 4,500 jobs and €80m in cuts could hit disadvantaged communities this year.</span></span></p>
<p><span ><span >The research by Harvey and the trade union received front page coverage in the Irish Examiner on Monday.</span></span></p>
<p><span ><span >&#8216;Changing Ireland&#8217; asked Minister Pat Carey that very day was he pleased with the coverage and he said he was, but he declined to say whether or not he agreed that cuts to the Community Sector were &#8220;disproportionate&#8221;.</span></span></p>
<p><span ><span >Brian&#8217;s research shows the Community Sector may lose 4,500 jobs in 2010 and is struggling with 9-10% cuts which is above the average.</span></span><b><span><span ><span ><o:p></o:p></span></span></span></b></p>
<p><span ><span >The</span></span><b><span ><span > Ballyphehane/Togher Community Development</span></span></b><b><span><span ><span > </span></span></span></b><b><span ><span >Project in Cork, Parents Alone Support Services CDP</span></span></b><span ><span > in Dublin and </span></span><b><span ><span >Minister Pat Carey, SIPTU&#8217;s Gerry Flanagan, independent councilor Cieren Perry</span></span><span ><span ><span > </span></span></span></b><span ><span >and the</span></span><b><span ><span > Community Worker&#8217;s Co-op&#8217;s Ann Irwin</span></span></b><span ><span > were among those interviewed for the 2-page spread inside.</span></span></p>
<p><b><i><span><span ><span >Examiner lead story:</span></span></span></i></b></p>
<p><b><span><a href="https://www.examiner.ie/ireland/4500-jobs-at-risk-80m-cut-for-social-schemes-123597.html"><i><span><span ><span >https://www.examiner.ie/ireland/4500-jobs-at-risk-80m-cut-for-social-schemes-123597.html</span></span></span></i></a></span></b><b><span><span ><span ><o:p></o:p></span></span></span></b></p>
<p><b><span><o:p><span ><span > </span></span></o:p></span></b></p>
<p><span><span ><span >Brian’s full report for IMPACT can be downloaded from:</span></span></span><b><span><span ><span ><o:p></o:p></span></span></span></b></p>
<p><b><span><a href="https://www.impact.ie/iopen24/pub/general/HarveyReport2010.pdf"><span><span ><span >https://www.impact.ie/iopen24/pub/general/HarveyReport2010.pdf</span></span></span></a><span ><span ><o:p></o:p></span></span></span></b></p>
<p><span><span ><span >There are online links to the Examiner’s coverage of the 2 CDPs:</span></span></span><b><span><span ><span ><o:p></o:p></span></span></span></b></p>
<p><b><span><a href="https://www.irishexaminer.com/archives/2010/0628/ireland/one-more-cut-and-were-gone-says-lone-parent-group-123539.html#ixzz0sKUbyEOc"><span><span ><span >https://www.irishexaminer.com/archives/2010/0628/ireland/one-more-cut-and-were-gone-says-lone-parent-group-123539.html#ixzz0sKUbyEOc</span></span></span></a></span></b></p>
<p><span><span ><span >AND</span></span></span><b><span><span ><span ><o:p></o:p></span></span></span></b></p>
<p><b><span><a href="https://www.examiner.ie/ireland/theres-work-being-done-that-cant-be-measured-on-paper-123538.html#ixzz0sKUQxens"><span><span ><span >https://www.examiner.ie/ireland/theres-work-being-done-that-cant-be-measured-on-paper-123538.html#ixzz0sKUQxens</span></span></span></a><span ><span ><o:p></o:p></span></span></span></b></p>
<p><span><span ><span >ALSO SEE:</span></span></span><b><span><span ><span ><o:p></o:p></span></span></span></b></p>
<p><b><span><span><span ><span ><a href="https://www.examiner.ie/ireland/community-groups-in-crisis-123537.html">https://www.examiner.ie/ireland/community-groups-in-crisis-123537.html</a></span></span></span></span></b><span lang="EN-GB"  ><o:p></o:p></span></p>
<p><span  ><span  ></span></span></p>
<p><span  ></p>
<p><span lang="EN-GB"><b><span ><span ><span>COMMENTS WELCOME (click on &#8216;Comments&#8217; below here)!<o:p></o:p></span></span></span></b></span></p>
<p><span lang="EN-GB"><b><span ><span ><span>PERSONAL ABUSE IS A NO-NO. PRAISE, COMMENT AND CRITICISM OF POLICY OR APPROACH IS COOL. GIVE YOUR NAME IF POSSIBLE, OR CLICK THE ‘ANONYMOUS’ KEY.</span></span></span></b></span></p>
<p></span></p>
<p>     </span></p>
<p>  </p>', 'Research work last month by Brian Harvey and IMPACT showed that 4,500 jobs and €80m in cuts could hit disadvantaged communities this year. The research by Harvey and the trade union received front page coverage in the Irish Examiner on Monday. ‘Changing Ireland’ asked Minister Pat Carey that very day was he pleased with the', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 349, 1, '2010-06-30T09:59:00Z', '2010-06-30T09:59:00Z', '2010-06-30T09:59:00Z')
