INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Appeal for reversal of cuts in addiction counselling', 'appeal-for-reversal-of-cuts-in-addiction-counselling', '<p>  </p>
<p><span lang="EN-GB"><span>Funding to drugs projects has been cut nationwide this year, despite protests, and today John Cregan, Fianna Fail TD, hit out at newly announced cuts to drugs services in County Limerick. </span></span></p>
<p><span><span lang="EN-GB"></span>The Youth Drug Prevent Project in Kilmallock and the Newcastle West Based Drugs Initiative have been told that their funding will end this month, meaning both projects will have to close their doors.</span></p>
<p><span lang="EN-GB"><span>John blamed the Mid-Western Regional Drugs Task Force for the loss of the two counsellors involved and said there would now be nowhere local for people struggling with addiction in these parts of Limerick to seek help.</span></span></p>
<p><span lang="EN-GB"><span>He appealed on the local radio station Live 95 FM for the cuts to be &#8220;reversed&#8221;.</span></span></p>
<p><span lang="EN-GB"><span>Ironically, John&#8217;s intervention comes just one day after drugs workers in Limerick city held a successful drugs information day (</span><a href="https://changingireland.blogspot.com/2010/06/work-goes-on-southills-day-of-action-on.html"><span>see yesterday&#8217;s blog repor</span></a><span>t) showing there were places for families and addicts to go in the city.</span></span></p>
<p>  </p>', 'Funding to drugs projects has been cut nationwide this year, despite protests, and today John Cregan, Fianna Fail TD, hit out at newly announced cuts to drugs services in County Limerick. The Youth Drug Prevent Project in Kilmallock and the Newcastle West Based Drugs Initiative have been told that their funding will end this month,', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 351, 1, '2010-06-24T17:02:00Z', '2019-09-13T10:59:06Z', '2010-06-24T17:02:00Z')
