INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('The work goes on – Southill’s day of action on drugs', 'the-work-goes-on-southills-day-of-action-on-drugs', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI_YDHtdKI/AAAAAAAAAFU/2BBb2atOE00/s1600/DSCF6628.JPG"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI_YDHtdKI/AAAAAAAAAFU/2BBb2atOE00/s400/DSCF6628.JPG" border="0" alt="" /></a><br /><span ><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI67FqVxyI/AAAAAAAAAEs/CYLbCWycTic/s1600/DSCF6610.JPG"><span><b><span ></span></b></span></a><b></p>
<div><b><span ><br /></span></b></div>
<p><span ><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI67FqVxyI/AAAAAAAAAEs/CYLbCWycTic/s1600/DSCF6610.JPG">&#8211; COMMUNITY WORK ON THE GROUND</a></span></b></span></p>
<div><span ><b><span ><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI67FqVxyI/AAAAAAAAAEs/CYLbCWycTic/s1600/DSCF6610.JPG"></a></span></b><b><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI67FqVxyI/AAAAAAAAAEs/CYLbCWycTic/s1600/DSCF6610.JPG"><span >&#8211; 100 ATTEND DRUGS INFO DAY IN SOUTHILL</span></a></b></p>
<div>
<div>
<div>
<div>
<div><span >&#8211; Limerick, June 23rd, 2010</span></div>
<div><span ><br /></span></div>
<div>
<div>
<div><span >The Local and Community Development Programme </span>is due to take off by the end of this year &#8211; the structures are being argued over up and down of the country &#8211; and in the meantime the work on the ground in communities continues.</div>
<div>
<div>
<div><span >Southill CDP in Limerick today brought together 12 staff from 10 agencies involved in anti-drugs work for a public information day on drugs.</span></div>
<div><span >A lot of parents brought along their children to see what drugs look like, so they would recognise the d</span>angers when confronted by the real thing.</div>
<div>&#8216;Changing Ireland&#8217; met a mother of an eight-year-old concerned about the way schoolchildren are being targeted. She was determined to educate her child before it was too late. Others sought advice on the day from Slainte, Aljeff, North Star, Cuan Mhuire, Victory Outreach from Cork and others on the way through addiction.</div>
<p>Caroline Keane is a community-based Drugs Education Worker and she says alcohol and nicotine are the most widely used drugs in Southill.</p>
<div><span >She was pleased at the end of the day: &#8220;We had 100 local people along today and 30 of them signed up for training.&#8221; The training includes joining a Community Addiction Studies course starting in September.</span></div>
<div><span ><br /></span></div>
<div>
<div><i><span >Group photo above: John Hehir, Denise McNamara and Zoe Hehir who</span></i></div>
<div><i><span><i><span >attended the drugs information day and organiser Caroline Keane.</span></i></span></i></div>
<div><i><span><i><span ><br /></span></i></span></i></div>
<div><i><span >Photos below: Close-up shots of of patches from the North Star quilt. Each patch is in memory of someone who died before their time.</span></i></div>
<div><i><span ><br /></span></i></div>
<div><span ><span >This report is the beginning in a series showing how local work around the country continues, while policy makers, politicians and community activists seek at the same time to influence the shape and structure of the new Local and Community Development Programme.</span></span></div>
</div>
</div>
</div>
</div>
</div>
</div>
</div>
</div>
</div>
<p></span><span ><br /></span><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI68MeBPII/AAAAAAAAAE8/SkjZEUAe0oE/s1600/DSCF6618.JPG"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI68MeBPII/AAAAAAAAAE8/SkjZEUAe0oE/s400/DSCF6618.JPG" border="0" alt="" /></a><span ><br /></span><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/TCI67j0NyOI/AAAAAAAAAE0/_L3fbJwAUkI/s1600/DSCF6613.JPG"><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/TCI67j0NyOI/AAAAAAAAAE0/_L3fbJwAUkI/s400/DSCF6613.JPG" border="0" alt="" /></a><span ><b><br /></b></span><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI67FqVxyI/AAAAAAAAAEs/CYLbCWycTic/s1600/DSCF6610.JPG"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCI67FqVxyI/AAAAAAAAAEs/CYLbCWycTic/s400/DSCF6610.JPG" border="0" alt="" /><b><br /></b></a></div>', '– COMMUNITY WORK ON THE GROUND – 100 ATTEND DRUGS INFO DAY IN SOUTHILL – Limerick, June 23rd, 2010 The Local and Community Development Programme is due to take off by the end of this year – the structures are being argued over up and down of the country – and in the meantime the', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 352, 1, '2010-06-23T15:50:00Z', '2010-06-23T15:50:00Z', '2010-06-23T15:50:00Z')
