INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('You can also follow us on Facebook!', 'you-can-also-follow-us-on-facebook', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCIs4vO79eI/AAAAAAAAAEk/dEokqokWKYk/s1600/facebook_sml.png"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/TCIs4vO79eI/AAAAAAAAAEk/dEokqokWKYk/s320/facebook_sml.png" border="0" alt="" /></a><span ><br /></span><a href="https://www.facebook.com/pages/Changing-Ireland/195484689356?ref=ts"><span >Follow &#8216;Changing Ireland&#8217; on facebook </span></a><span >and join over 300 members on our fanpage.</span></p>
<div><span >Contribute ideas, suggestions, comments and stir debate on community issues and community work.</span></div>
<div><span >In recent work via facebook, we have worked alongside members of the facebook sit</span><a href="https://www.facebook.com/group.php?gid=158644514143&amp;ref=ts"><span >e &#8216;Hands Off Community Development&#8217;</span></a><span > and </span><a href="https://www.paveepoint.ie/"><span >Pavee Point</span></a><span > to counteract racist websites. Two anti-Traveller sites (</span><a href="https://www.facebook.com/photo.php?pid=4008698&amp;id=195484689356"><span >here&#8217;s what one of the offensive sites looked like</span></a><span >) were removed by facebook after presssure from activists and concerned citizens.</span></div>
<div><span >It was a case of every cloud having a silver lining. Community workers and volunteers came together on facebook to work together to fight cutbacks and thanks to that coming together they were in a position to force facebook to close down the racist websites.</span></div>
<div><span ><br /></span></div>
<div><span >Meanwhile, it&#8217;s time this blog was brought to life once more. Feedback welcome.</span></div>', 'Follow ‘Changing Ireland’ on facebook and join over 300 members on our fanpage. Contribute ideas, suggestions, comments and stir debate on community issues and community work. In recent work via facebook, we have worked alongside members of the facebook site ‘Hands Off Community Development’ and Pavee Point to counteract racist websites. Two anti-Traveller sites (here’s', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 353, 1, '2010-06-23T14:38:00Z', '2019-09-13T10:59:49Z', '2010-06-23T14:38:00Z')
