INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('28 pages of news, debate and updates – OUR LATEST EDITION!', '28-pages-of-news-debate-and-updates-our-latest-edition', '<p><a href="https://1.bp.blogspot.com/_cgq3tUEQMDo/S9hYXbOJaeI/AAAAAAAAAEc/U1_nYdCCglU/s1600/Changing+Ireland+Issue+32+COVER.png"><img decoding="async" src="https://1.bp.blogspot.com/_cgq3tUEQMDo/S9hYXbOJaeI/AAAAAAAAAEc/U1_nYdCCglU/s400/Changing+Ireland+Issue+32+COVER.png" border="0" alt="" /></a><br /><span ><span >Yes, the latest &#8216;Changing Ireland&#8217; is out and it features:<br />&#8211; 6 pages of Sector news<br />&#8211; A Community Work report from Palestine<br />&#8211; Volunteering while unemployed<br />&#8211; New Programme: news, debate &amp; updates on the new Local and Community Development Programme<br />&#8211; Social Enterprise Offers A Real Solution for Ireland </span></span></p>
<div><span ><span >&#8211; An interview with former Community Minister Eamon O&#8217;Cuiv<br />&#8211; Plus letters to our agony uncle Help Me Horace!<br />HEY, WHAT DO YOU THINK OF IT? ANY STORY IDEAS FOR OUR SUMMER EDITION?<br />THANKS TO everyone who contributed to the current edition and to those who suggested ideas and/or critical advice.</span></span></div>', 'Yes, the latest ‘Changing Ireland’ is out and it features:– 6 pages of Sector news– A Community Work report from Palestine– Volunteering while unemployed– New Programme: news, debate & updates on the new Local and Community Development Programme– Social Enterprise Offers A Real Solution for Ireland – An interview with former Community Minister Eamon O’Cuiv–', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 354, 1, '2010-04-28T15:42:00Z', '2010-04-28T15:42:00Z', '2010-04-28T15:42:00Z')
