INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('A good book to ask your library to buy –', 'a-good-book-to-ask-your-library-to-buy', '<p><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/S30-IvuqNaI/AAAAAAAAAEU/9_2pe2QeMnY/s1600-h/Youth+and+Community+Work+journal.jpg"><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/S30-IvuqNaI/AAAAAAAAAEU/9_2pe2QeMnY/s200/Youth+and+Community+Work+journal.jpg" border="0" alt="" /><span><span ><span >If you’re looking for new perspectives on youthwork in Ireland, then a new journal maps out new thinking on this area of work.</span></span></span></a></p>
<div><span ><span></p>
<p><span ><span >‘Youth and Community Work in Ireland: Critical Perspectives’ was published recently by lecturers from Cork.</span></span></p>
<p><span ><span >It is currently the only text that covers the theory and practice of youth and community work in Ireland.</span></span></p>
<p><span ><span >The authors aim with the book to reach a broad audience including workers, volunteers, students, policy makers and academics in youth and community work and related fields.</span></span></p>
<p><span ><span >It is, they say, “a key text for youth and community work degrees and related programmes in universities and colleges and a resource for youth and community work groups, organisations and projects.”</span></span></p>
<p><span ><span >For more information and to buy a copy – or indeed to ask your local library to purchase <span ><span ><span >your copy – log onto </span></span><span ><span ><a href="https://www.blackhallpublishing.com/index.php/youth-and-community-work-in-ireland-critical-perspectives.html">the publishers website Blackhall Publishing.</a></span></span></span></span></span></p>
<p><span ><span ><a href="https://www.blackhallpublishing.com/index.php/youth-and-community-work-in-ireland-critical-perspectives.html"></a>The authors Catherine Forde, Rosie Meade and Elizabeth Kiely are lecturers in the Department of Applied Social Studies in University College Cork and have published widely on youth and community work.</span></span></p>
<p><span ><span ><span >  </span></span> </span></p>
<p></span></span></div>', 'If you’re looking for new perspectives on youthwork in Ireland, then a new journal maps out new thinking on this area of work. ‘Youth and Community Work in Ireland: Critical Perspectives’ was published recently by lecturers from Cork. It is currently the only text that covers the theory and practice of youth and community work', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 355, 1, '2010-02-18T13:07:00Z', '2020-01-22T13:28:29Z', '2010-02-18T13:07:00Z')
