INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('14 CDPs lose funding following review', '14-cdps-lose-funding-following-review', '<p><span ><span >14 CDPs are to lose funding following a review by the Department of Community, Rural and Gaeltacht Affairs. 13 are in Dublin and one in Clonmel, Co. Tipperary.</span></span></p>
<div><span><span ><span >The Community Development Project Appeals Board report, released on Friday, January 29th, said issues considered in the review included the “identification of potential for achieving improved efficiencies”.</span></span></span><span ><span ><br /></span></span></p>
<div><span ><span >For more, check <a href="https://changingireland.ie/">our main website&#8217;s homepage</a> for relevant links. You can also read the</span></span><span ><span ><span ><a href="https://www.irishtimes.com/newspaper/ireland/2010/0130/1224263435675.html"> &#8216;Irish Times&#8217; report</a> on the review body&#8217;s decision.</span></span></span></div>
</div>', '14 CDPs are to lose funding following a review by the Department of Community, Rural and Gaeltacht Affairs. 13 are in Dublin and one in Clonmel, Co. Tipperary. The Community Development Project Appeals Board report, released on Friday, January 29th, said issues considered in the review included the “identification of potential for achieving improved efficiencies”.', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 356, 1, '2010-02-03T19:38:00Z', '2019-09-13T10:59:17Z', '2010-02-03T19:38:00Z')
