INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Poor Can’t Pay Campaign launches Video', 'poor-cant-pay-campaign-launches-video', '<p><span><b></p>
<p><span><span>Some of Ireland’s leading NGO’s and trade unions have joined forces to launch a new campaign called “The Poor Can’t Pay” which aims to mobilise active opposition to proposed cuts to basic social welfare payments or the minimum wage.  </span></span></p>
<p><span><span> </span></span></p>
<p><span><span>The Poor Can&#8217;t Pay campaign said that people earning the minimum wage or living on social welfare did not cause Ireland&#8217;s economic crisis and should not be forced to pay the price of the recession.</span></span></p>
<p><span><span> </span></span></p>
<p><span><span>The campaign was launched as a joint initiative by the following NGO’s and trade unions: Age Action, </span></span><span lang="EN-IE"><span><span>Barnardos, CORI Justice, EAPN, Focus Ireland, INOU, Mandate, National Women’s Council of Ireland, SIPTU and </span></span></span><span><span>SVP</span></span><span lang="EN-IE"><span><span>.</span></span></span></p>
<p><span lang="EN-IE"><span><span> </span></span></span></p>
<p></b></p>
<p><object height="255" width="420"><param name="movie" value="https://www.youtube.com/v/OmJ4sNFm9Cc&amp;hl=en_US&amp;fs=1&amp;"><param name="allowFullScreen" value="true"><param name="allowscriptaccess" value="always"><embed src="https://www.youtube.com/v/OmJ4sNFm9Cc&amp;hl=en_US&amp;fs=1&amp;" type="application/x-shockwave-flash" allowscriptaccess="always" allowfullscreen="true" height="255" width="420"></embed></object></span></p>', 'Some of Ireland’s leading NGO’s and trade unions have joined forces to launch a new campaign called “The Poor Can’t Pay” which aims to mobilise active opposition to proposed cuts to basic social welfare payments or the minimum wage. The Poor Can’t Pay campaign said that people earning the minimum wage or living on social', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 358, 1, '2009-12-03T10:13:00Z', '2019-09-13T10:59:31Z', '2009-12-03T10:13:00Z')
