INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Earn an award – 3 days and the clock is ticking!', 'earn-an-award-3-days-and-the-clock-is-ticking', '<p><a href="https://1.bp.blogspot.com/_cgq3tUEQMDo/SwynlLq6mKI/AAAAAAAAAD8/wPLf5br_C6A/s1600/Aontas+awards+%2709.jpg"><img decoding="async" src="https://1.bp.blogspot.com/_cgq3tUEQMDo/SwynlLq6mKI/AAAAAAAAAD8/wPLf5br_C6A/s320/Aontas+awards+%2709.jpg" border="0" alt="" /></a></p>
<p><span ><b><span >An Aontas award could be yours! Nominate your local adult learning project for an AONTAS STAR Award and do it fast! </span></b></span><span ><span ><o:p></o:p></span></span></p>
<p><span ><span >The deadline for entries is this Friday, November 27</span></span><sup><span ><span >th</span></span></sup><span ><span >.</span></span><span ><span ><o:p></o:p></span></span></p>
<p><span ><span >The AONTAS awards, now in its fourth year, celebrate teamwork, and recognise the achievements of those involved in adult learning around the country.   </span></span><span ><span ><o:p></o:p></span></span></p>
<p><span ><span >It&#8217;s easy to enter. Nominations can be submitted online through the website www.adultlearnersfestival.com, or by email to mail@aontas.com. </span></span></p>
<p><span ><span >A sample nomination form is available online to assist people completing their nominations.</span></span><span ><span ><o:p></o:p></span></span></p>
<p><span ><b><span >More info: www.aontas.com</span></b></span><o:p></o:p></p>
<p>  </p>', 'An Aontas award could be yours! Nominate your local adult learning project for an AONTAS STAR Award and do it fast! The deadline for entries is this Friday, November 27th. The AONTAS awards, now in its fourth year, celebrate teamwork, and recognise the achievements of those involved in adult learning around the country. It’s easy', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 360, 1, '2009-11-25T03:28:00Z', '2019-09-13T11:00:20Z', '2009-11-25T03:28:00Z')
