INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('CDPs on Liveline', 'cdps-on-liveline', '<p>On Monday 9th November, Joe Duffy got a call from a Kathleen O&#8217;Neill in Kilbarrack CDP about the proposed changes to the CDP programme. Once it got started, more people started ringing in   including:<br />Mary Catherine Heanue from Inishturk Development Office<br />Ursula McKenna from Dochas for Women, Monaghan<br />Bray Traveller&#8217;s CDP&#8217;s Jim O&#8217;Brien,<br />Maurice McConville from Le Chéile CDP,<br />Martin Hamilton from Kilmore West CDP,<br />Mary McClorey from Southside CDP in Drogheda,<br />Harry Murphy from Crumlin CDP and<br />Liz Riches from Ballybeg CDP in Waterford.<br />Joe Duffy and the RTE listeners got the  low down on what CDPs do for their communities around the country</p>
<p><a href="https://www.rte.ie/podcasts/2009/pc/pod-v-091109-34m36s-livelinecdp.mp3">Listen to the CDP discussion on Liveline. </a>(mp3 file)</p>', 'On Monday 9th November, Joe Duffy got a call from a Kathleen O’Neill in Kilbarrack CDP about the proposed changes to the CDP programme. Once it got started, more people started ringing in including:Mary Catherine Heanue from Inishturk Development OfficeUrsula McKenna from Dochas for Women, MonaghanBray Traveller’s CDP’s Jim O’Brien,Maurice McConville from Le Chéile CDP,Martin', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 361, 1, '2009-11-10T09:59:00Z', '2009-11-10T09:59:00Z', '2009-11-10T09:59:00Z')
