INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New Community Workers Co-op website', 'new-community-workers-co-op-website', '<p><a href="https://cwc.ie/"><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/Ssxp2HqvpOI/AAAAAAAAAD0/A0yXH5vq6Z8/s1600-h/CWC.png"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/Ssxp2HqvpOI/AAAAAAAAAD0/A0yXH5vq6Z8/s320/CWC.png" border="0" alt=""id="BLOGGER_PHOTO_ID_5389799232547824866" /></a></a><br /><a href="https://www.cwc.ie/">The Community Workers Co-op have a new website (click HERE)</a>. It&#8217;s been a while in the pipeline and was worth the wait!</p>', 'The Community Workers Co-op have a new website (click HERE). It’s been a while in the pipeline and was worth the wait!', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 363, 1, '2009-10-07T10:10:00Z', '2009-10-07T10:10:00Z', '2009-10-07T10:10:00Z')
