INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Health Corr gives CDPs a ringing endorsement', 'health-corr-gives-cdps-a-ringing-endorsement', '<p><a href="https://2.bp.blogspot.com/_cgq3tUEQMDo/SsKj9ZDMkOI/AAAAAAAAADs/mHW2iHZrxN0/s1600-h/Drivetime+Sept+24,+%2709+on+CDPs.png"><img decoding="async" src="https://2.bp.blogspot.com/_cgq3tUEQMDo/SsKj9ZDMkOI/AAAAAAAAADs/mHW2iHZrxN0/s200/Drivetime+Sept+24,+%2709+on+CDPs.png" border="0" alt=""id="BLOGGER_PHOTO_ID_5387048379380175074" /></a></p>
<p><a href="https://www.rte.ie/news/2009/0924/drivetime.html"><span>JOURNALIST GIVES BRILLIANT EXPLANATION OF WHAT CDPs REALLY DO</span></a></p>
<p>The author of the most <a href="https://www.newisland.ie/node/462">penetrating book written in recent years on the Irish health service</a> has given CDPs a ringing endorsement in a <a href="https://www.rte.ie/news/2009/0924/drivetime.html">7-minute interview on RTE&#8217;s Drivetime.</a> (Click &#8216;community health workers&#8217;).<br />Sara Burke has described the work that CDPs do as exceptional value for money and she paid tribute to volunteers&#8217; involvement and the ability of projects to do a great many things with very limited resources. While focusing chiefly on CDPs, Sara also drew attention to equally good work done by drugs projects, Family Resource Centres and a range of others. <br /><span>Her interview was broadcast on Thursday last, September 24th,</span> <span>and <a href="https://saraburke.wordpress.com/2009/09/29/community-sector-cuts-will-hurt-the-poorest-communities/#more-191">Sara has just published a written report on CDPs on her blog.</a></span></p>
<p>COMMENT BELOW!!!</p>', 'JOURNALIST GIVES BRILLIANT EXPLANATION OF WHAT CDPs REALLY DO The author of the most penetrating book written in recent years on the Irish health service has given CDPs a ringing endorsement in a 7-minute interview on RTE’s Drivetime. (Click ‘community health workers’).Sara Burke has described the work that CDPs do as exceptional value for money', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 364, 1, '2009-09-29T23:56:00Z', '2009-09-29T23:56:00Z', '2009-09-29T23:56:00Z')
