INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('National Community Development Forum says merger “an attack on the poor”', 'national-community-development-forum-says-merger-an-attack-on-the-poor', '<p><span><span>The </span></span><span><span><a href="https://www.nationalcdf.blogspot.com/">National Community Development Forum</a></span></span><span><span>, the representative body for the country&#8217;s 180 CDPs, has said it rejects proposals by Minister of State John Curran to merge two programmes, arguing that in the course of that process the &#8220;scheme will disempower the most marginalised of local communities across Ireland.&#8221;</p>
<p>The Forum said there was no consultation, the plan was &#8220;an attack on the poor&#8221; and made a mockery of community development educational initiatives.</p>
<p>Forum chairperson Larry McCarthy said, “This move&#8230; will terminate the involvement of 2000 volunteers in deciding a little of what happens in their own communities and that undermines everything that Community Development stands for.”<br />The&nbsp;Forum called for talks with the Minister so he could &#8220;clarify some of the issues around the lack of consultation with, not alone the CDPs, but the service users.&#8221;</p>
<p></span></span><span><span><span>For the full text, check</span></span><a href="https://www.nationalcdf.blogspot.com/"><span><span> the Forum&#8217;s blog.</span></span></a><span><span></span></span></span></p>
<div><span><br /></span></div>
<div><b><span><span>FOR AN UPDATE, SEE OUR B</span></span></b><b><span><span><a href="https://changingireland.blogspot.com/2010/11/where-cdps-now-stand.html">LOG ENTRY DATED NOVEMBER 25th, 2010</a>, ON &#8216;Where CDPs Now Stand&#8217;.</span></span></b></div>', 'The National Community Development Forum, the representative body for the country’s 180 CDPs, has said it rejects proposals by Minister of State John Curran to merge two programmes, arguing that in the course of that process the “scheme will disempower the most marginalised of local communities across Ireland.” The Forum said there was no consultation,', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 365, 1, '2009-09-29T23:44:00Z', '2009-09-29T23:44:00Z', '2009-09-29T23:44:00Z')
