INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Blanchardstown: Bonus for Volunteers!', 'blanchardstown-bonus-for-volunteers', '<p><a href="https://4.bp.blogspot.com/_cgq3tUEQMDo/SsIbtOODk7I/AAAAAAAAADk/DUPt7xAdGOs/s1600-h/V+De+Paul+bonus+copy.jpg"></p>
<blockquote></blockquote>
<blockquote></blockquote>
<blockquote></blockquote>
<blockquote></blockquote>
<p><img decoding="async" src="https://4.bp.blogspot.com/_cgq3tUEQMDo/SsIbtOODk7I/AAAAAAAAADk/DUPt7xAdGOs/s200/V+De+Paul+bonus+copy.jpg" border="0" alt="" /></a><br />Volunteers who work at the Vincent De Paul shop in Blanchardstown got a pleasant surprise last week when members of the local Traveller Community Employment scheme presented them with a variety of organic vegetables.<br />The vegetables were grown on the Travellers Allotment.</p>
<div>Our picture – from CE worker Tom Toner &#8211; shows Geraldine Collins of Blanchardstown Travellers CE (right) presenting a basket of mushrooms to shop manager Marie Murray (left) surrounded by shop volunteers and one of the gardeners.<br />The CE scheme is sponsored by the local CDP, the Blanchardstown Traveller Development Group.</div>', 'Volunteers who work at the Vincent De Paul shop in Blanchardstown got a pleasant surprise last week when members of the local Traveller Community Employment scheme presented them with a variety of organic vegetables.The vegetables were grown on the Travellers Allotment. Our picture – from CE worker Tom Toner – shows Geraldine Collins of Blanchardstown', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 366, 1, '2009-09-29T14:30:00Z', '2009-09-29T14:30:00Z', '2009-09-29T14:30:00Z')
